import assert from 'node:assert';
import { test } from 'node:test';
import { 
  createState, 
  collides, 
  step, 
  frame, 
  WIDTH, 
  HEIGHT, 
  BRICK_W, 
  BRICK_H,
  BRICK_TOP
} from '../game/neon.js';

// Mock Canvas Context
const mockCtx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1: Ball should bounce off brick (no tunneling)', () => {
  const state = createState(1);
  // Ball moving UP toward a brick
  state.ball.x = WIDTH / 2;
  state.ball.y = BRICK_TOP + BRICK_H + 10;
  state.ball.vx = 0;
  state.ball.vy = -200; // moving UP

  // Position a brick right in front of it
  state.bricks = [{
    x: WIDTH / 2 - BRICK_W / 2,
    y: BRICK_TOP,
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10
  }];

  // Simulate one frame where collision happens
  state.ball.y = BRICK_TOP + BRICK_H + 2; 

  frame(mockCtx, state);

  // The ball should have reversed direction (vy should be > 0)
  assert.strictEqual(Math.sign(state.ball.vy), 1, 'Ball should bounce DOWN after hitting bottom of brick');
});

test('D2: Ball should not stick to brick (resolution)', () => {
  const state = createState(1);
  state.ball.x = WIDTH / 2;
  state.ball.y = BRICK_TOP + BRICK_H - 2; 
  state.ball.vx = 0;
  state.ball.vy = -200;

  state.bricks = [{
    x: WIDTH / 2 - BRICK_W / 2,
    y: BRICK_TOP,
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10
  }];

  // Frame 1: flip vy to 200.
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vy, 200);

  // Frame 2: if it still collides, it flips back to -200.
  frame(mockCtx, state);
  assert.notStrictEqual(state.ball.vy, -200, 'Ball should not flip velocity back due to overlap (sticking)');
});

test('D3: Ball should not double-bounce on seams', () => {
  const state = createState(1);
  state.ball.x = WIDTH / 2 + 52; // Exactly on the seam between two bricks
  state.ball.y = BRICK_TOP + 10;
  state.ball.vx = 200; // moving RIGHT
  state.ball.vy = 0;

  state.bricks = [
    { x: WIDTH / 2 - 20, y: BRICK_TOP, w: BRICK_W, h: BRICK_H, alive: true, points: 10 },
    { x: WIDTH / 2 + BRICK_W - 20, y: BRICK_TOP, w: BRICK_W, h: BRICK_H, alive: true, points: 10 }
  ];

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx, -200, 'Ball should only bounce once even if overlapping two bricks');
});

test('D4: Ball should not tunnel through bricks at high speed', () => {
  const state = createState(10);
  const currentSpeed = 1070; 

  state.ball.x = WIDTH / 2;
  state.ball.y = BRICK_TOP + BRICK_H + 5;
  state.ball.vx = 0;
  state.ball.vy = -currentSpeed;

  state.bricks = [{
    x: WIDTH / 2 - BRICK_W / 2,
    y: BRICK_TOP,
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10
  }];

  // Simulate the game loop: step() then frame()
  const dt = 0.05;
  step(state, dt); // moves ball by 53.5px UP, now it's ABOVE the brick
  frame(mockCtx, state);

  // The ball should have bounced even if it tunneled through the brick in step()
  assert.strictEqual(Math.sign(state.ball.vy), 1, 'Ball should bounce even if it tunneled through the brick');
});

# Symptôme joueur : « la balle passe à travers les briques au lieu de rebondir »

## D1 — Absence de rebond sur briques

- **Famille** : Traversée (basique)
- **Symptôme joueur** : la balle traverse les briques sans changer de direction.
- **Cause** : `game/neon.js:204` — Le bloc de collision détecte l'impact et détruit la brique, mais ne modifie jamais la vitesse de la balle.
- **Invariant violé** : Tout contact avec une brique doit entraîner une réflexion de la vitesse sur l'axe perpendiculaire à la face touchée.
- **Déclencheur** : N'importe quel contact avec une brique.
- **Attendu** : `vy` inversé si contact haut/bas, `vx` inversé si contact gauche/droite.
- **Référence** : [Collision Resolution](https://learnopengl.com/In-Practice/2D-Collision-Resolution) — Identifier la face d'impact pour inverser le bon axe.
- **Cas test** :
  ```js
  test('D1: Ball should bounce off brick', () => {
    // Ball moving UP toward a brick bottom
    state.ball.y = BRICK_TOP + BRICK_H + 2; 
    state.ball.vy = -200;
    frame(mockCtx, state);
    assert.strictEqual(Math.sign(state.ball.vy), 1);
  });
  ```
- **Rouge aujourd'hui** : `-1 !== 1`
- **Discrimine** : Une correction qui oublierait de traiter l'un des axes.
- **Vert quand** : la balle repart dans la direction opposée à la face touchée.

## D2 — Balle collante (Sticking)

- **Famille** : Collant
- **Symptôme joueur** : la balle vibre ou traverse lentement une brique après l'avoir touchée.
- **Cause** : Absence de repositionnement après le rebond. La balle reste en collision au frame suivant, et la vitesse est ré-inversée.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle de la brique.
- **Déclencheur** : Collision profonde où `v * dt` ne suffit pas à sortir la balle du rectangle au frame suivant.
- **Attendu** : La balle est repositionnée sur le bord de la brique.
- **Référence** : [AABB Resolution](https://gamedev.stackexchange.com/questions/243513/resolving-multiple-collisions) — Resolve by pushing out along the axis of least penetration.
- **Cas test** :
  ```js
  test('D2: Ball should not stick', () => {
    state.ball.y = BRICK_TOP + BRICK_H - 2; // deep overlap
    state.ball.vy = -200;
    frame(mockCtx, state); // bounce 1: vy = 200
    frame(mockCtx, state); // bounce 2: vy = -200 (FAIL)
    assert.notStrictEqual(state.ball.vy, -200);
  });
  ```
- **Rouge aujourd'hui** : `-200 !== 200`
- **Discrimine** : Une correction qui se contente d'inverser la vitesse sans repositionner.
- **Vert quand** : la balle ne subit qu'un seul rebond malgré le recouvrement initial.

## D3 — Double inversion sur couture (Ghost Collision)

- **Famille** : Double inversion
- **Symptôme joueur** : la balle traverse une rangée de briques horizontalement en ignorant les collisions sur les bords.
- **Cause** : Traitement séquentiel des briques dans une boucle. Si la balle touche deux briques sur le même axe dans la même frame, `vx = -vx` est appliqué deux fois.
- **Invariant violé** : Un rebond par passe et par axe.
- **Déclencheur** : Balle chevauchant deux briques (`ball.r > BRICK_GAP`).
- **Attendu** : Un seul rebond est enregistré pour l'ensemble des briques touchées sur un même axe.
- **Référence** : [Tile Seam Ghost Collision](https://www.youtube.com/watch?v=nh37K1UMe_s)
- **Cas test** :
  ```js
  test('D3: No double-bounce on seams', () => {
    state.ball.x = WIDTH/2 + 52; // on seam
    state.ball.vx = 200;
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vx, -200);
  });
  ```
- **Rouge aujourd'hui** : `200 !== -200`
- **Discrimine** : Une correction qui traite chaque brique indépendamment sans tracker les rebonds de la frame.
- **Vert quand** : `vx` n'est inversé qu'une seule fois.

## D4 — Traversée à haute vitesse (Tunneling)

- **Famille** : Traversée
- **Symptôme joueur** : la balle passe à travers les briques sans aucune interaction à haut niveau.
- **Cause** : Détection discrète. Si `v * dt > BRICK_H + 2*r`, la balle peut se retrouver de l'autre côté de la brique entre deux frames.
- **Invariant violé** : Aucun obstacle franchi sans rebond, quel que soit le pas.
- **Déclencheur** : Niveau 6+ ($v > 680$ px/s) avec $dt$ max (0.05s).
- **Attendu** : La collision est détectée même si la balle a "sauté" par-dessus le corps de la brique.
- **Référence** : [Swept AABB](https://blog.hamaluik.ca/posts/swept-aabb-collision-using-minkowski-difference/)
- **Cas test** :
  ```js
  test('D4: No tunneling at high speed', () => {
    state.ball.y = BRICK_TOP + BRICK_H + 5;
    state.ball.vy = -1070;
    step(state, 0.05); // moves ball completely above brick
    frame(mockCtx, state);
    assert.strictEqual(Math.sign(state.ball.vy), 1);
  });
  ```
- **Rouge aujourd'hui** : `-1 !== 1`
- **Discrimine** : Une correction basée sur le simple recouvrement AABB.
- **Vert quand** : la balle rebondit même en cas de saut de position.

