test('D1: Ball should bounce off brick (no tunneling)', () => {
  const state = createState(1);
  // Ball moving UP toward a brick
  state.ball.x = WIDTH / 2;
  state.ball.y = BRICK_TOP + BRICK_H + 10;
  state.ball.vx = 0;
  state.ball.vy = -200; // moving UP

  // Position a brick right in front of it
  state.bricks = [{
    x: WIDTH / 2 - BRICK_W / 2,
    y: BRICK_TOP,
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10
  }];

  // Use step instead of frame
  state.ball.y = BRICK_TOP + BRICK_H + 2; 
  step(state, 0.01);

  // The ball should have reversed direction (vy should be > 0)
  assert.strictEqual(Math.sign(state.ball.vy), 1, 'Ball should bounce DOWN after hitting bottom of brick');
});

test('D2: Ball should not stick to brick (resolution)', () => {
  const state = createState(1);
  state.ball.x = WIDTH / 2;
  state.ball.y = BRICK_TOP + BRICK_H - 2; 
  state.ball.vx = 0;
  state.ball.vy = -200;

  state.bricks = [{
    x: WIDTH / 2 - BRICK_W / 2,
    y: BRICK_TOP,
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10
  }];

  // Frame 1: bounce
  step(state, 0.01);
  assert.strictEqual(state.ball.vy, 200);

  // Frame 2: if it still collides, it flips back to -200.
  // Our implementation in step() now repositions the ball.
  step(state, 0.01);
  assert.notStrictEqual(state.ball.vy, -200, 'Ball should not flip velocity back due to overlap (sticking)');
});

