  }];

  // Simulate one frame where collision happens
  // dt = 0.01s -> dy = -2px. 
  // Ball is at y = BRICK_TOP + BRICK_H + 10. 
  // Bottom of brick is at BRICK_TOP + BRICK_H.
  // We need to move the ball into the brick.
  state.ball.y = BRICK_TOP + BRICK_H + 2; 
  // Ball.y - r = BRICK_TOP + BRICK_H + 2 - 7 = BRICK_TOP + BRICK_H - 5.
  // Ball is overlapping the brick.

  frame(mockCtx, state);

  // The ball should have reversed direction (vy should be > 0)
  assert.strictEqual(Math.sign(state.ball.vy), 1, 'Ball should bounce DOWN after hitting bottom of brick');
});

test('D2: Ball should not stick to brick (resolution)', () => {
  // This test is for after D1 is "naively" fixed by just flipping vy.
  // If we just flip vy, but the ball is still inside the brick, 
  // the next frame will flip it again.

  const state = createState(1);
  state.ball.x = WIDTH / 2;
  state.ball.y = BRICK_TOP + BRICK_H + 2; 
  state.ball.vx = 0;
  state.ball.vy = -200;

  state.bricks = [{
    x: WIDTH / 2 - BRICK_W / 2,
    y: BRICK_TOP,
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10
  }];

  // First frame: collision detected, vy flipped to +200.
  frame(mockCtx, state);

  // Second frame: if not pushed out, it still collides.
  // In a real game loop: step() then frame().
  // step(state, 0.01) -> ball.y += 200 * 0.01 = 2. 
  // Ball.y was BRICK_TOP + BRICK_H + 2. Now it's BRICK_TOP + BRICK_H + 4.
  // It might still be overlapping if it was deep.

  // Let's force it to be deep.
  state.ball.y = BRICK_TOP + BRICK_H - 2; // Ball center is 2px ABOVE brick bottom
  // ball.y + r = BRICK_TOP + BRICK_H - 2 + 7 = BRICK_TOP + BRICK_H + 5.
  // ball.y - r = BRICK_TOP + BRICK_H - 2 - 7 = BRICK_TOP + BRICK_H - 9.
  // Definitely overlapping.

  state.ball.vy = -200;

  // Frame 1: flip vy to 200.
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vy, 200);

  // Frame 2: if it still collides, it flips back to -200.
  frame(mockCtx, state);
  assert.notStrictEqual(state.ball.vy, -200, 'Ball should not flip velocity back due to overlap (sticking)');
});

test('D3: Ball should not double-bounce on seams', () => {
  const state = createState(1);
  state.ball.x = WIDTH / 2;
  state.ball.y = BRICK_TOP + 10; // Inside bricks height
  state.ball.vx = 200; // moving RIGHT
  state.ball.vy = 0;

  // Two bricks side by side, no gap (or ball spans the gap)
  state.bricks = [
    { x: WIDTH / 2 - 20, y: BRICK_TOP, w: BRICK_W, h: BRICK_H, alive: true, points: 10 },
    { x: WIDTH / 2 + BRICK_W - 20, y: BRICK_TOP, w: BRICK_W, h: BRICK_H, alive: true, points: 10 }
  ];

  // Ball is at x = WIDTH/2. 
  // Brick 1: [WIDTH/2 - 20, WIDTH/2 - 20 + 72] = [WIDTH/2 - 20, WIDTH/2 + 52]
  // Brick 2: [WIDTH/2 + 72 - 20, WIDTH/2 + 72 - 20 + 72] = [WIDTH/2 + 52, WIDTH/2 + 124]
  // Ball is at x = WIDTH/2, r = 7. 
  // Ball spans [WIDTH/2 - 7, WIDTH/2 + 7].
  // It overlaps Brick 1.

  // If the ball was positioned so it overlaps BOTH bricks...
  state.ball.x = WIDTH/2 + 52; // Exactly on the seam

  // Now it overlaps both Brick 1 (x+w = 52) and Brick 2 (x = 52)
  // because of the radius.

  frame(mockCtx, state);

  // If it bounced twice, vx would be reversed and then reversed again (back to 200).
  // It should have bounced ONCE (vx = -200).
  assert.strictEqual(state.ball.vx, -200, 'Ball should only bounce once even if overlapping two bricks');
});

